// tongTien = "total amount", gio = "cart", mon = "item", soLuong = "quantity"
const MENU = { "ca-phe-den": 25000, "ca-phe-sua": 29000, "tra-dao": 34500, "banh-mi": 20000 };

function tongTien(gio) {
  let tong = 0;
  for (const dong of gio) tong += MENU[dong.mon] * dong.soLuong;
  return tong;
}

const gioThu = [
  { ten: "empty cart", gio: [], mong: 0 },
  { ten: "one cup", gio: [{ mon: "ca-phe-sua", soLuong: 1 }], mong: 29000 },
  { ten: "two items", gio: [{ mon: "ca-phe-den", soLuong: 2 }, { mon: "banh-mi", soLuong: 1 }], mong: 70000 },
];
for (const c of gioThu) {
  const that = tongTien(c.gio);
  console.log(c.ten + ": " + (that === c.mong ? "pass" : "wrong (got " + that + ", expected " + c.mong + ")"));
}
